/* prog43_catalan.c
 * Re‑implementation of the original binary's observable behaviour.
 *
 * The program expects a single decimal integer argument n (1 ≤ n ≤ 30)
 * and prints the n‑th Catalan number.
 * For all error cases it prints a fixed message and exits with code 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_N 30

/* Compute Catalan numbers up to MAX_N and store them in the array.
 * The array is indexed from 0, i.e. cat[0] = C1 = 1, cat[1] = C2 = 2, …
 */
static void fill_catalan(unsigned long long cat[MAX_N])
{
    cat[0] = 1ULL;                     /* C1 */
    for (int k = 1; k < MAX_N; ++k) {
        unsigned long long sum = 0ULL;
        for (int i = 0; i < k; ++i) {
            sum += cat[i] * cat[k - 1 - i];
        }
        cat[k] = sum;
    }
}

/* Return 1 if the whole string *s* consists of a decimal integer that fits
 * into a signed long and store the value in *out*.  Otherwise return 0.
 */
static int parse_long(const char *s, long *out)
{
    char *endptr;
    errno = 0;
    long val = strtol(s, &endptr, 10);

    if (errno != 0)               /* overflow / underflow */
        return 0;
    if (endptr == s)              /* no digits at all */
        return 0;
    if (*endptr != '\0')          /* extra characters after the number */
        return 0;

    *out = val;
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    long n;
    if (!parse_long(argv[1], &n) || n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    unsigned long long cat[MAX_N];
    fill_catalan(cat);

    printf("%llu\n", cat[n - 1]);
    return 0;
}
